-- Local development catalogue only. This seed creates no Auth users or credentials.

insert into public.regions (slug, name, hero_title, hero_text, overview, sort_order, status, published_at)
values
    ('east-africa', 'East Africa', 'East Africa is where classic safari meets the Indian Ocean, primate forests, and highland culture.', 'Start here if your ideal trip includes big wildlife, gorilla or chimpanzee trekking, strong guide networks, and a route that can still end with Indian Ocean calm.', 'East Africa remains one of the continent''s highest-demand regions for safari, gorilla trekking, coast add-ons, and premium conservation travel. Kenya and Tanzania lead the classic plains circuits, while Uganda and Rwanda anchor primate-led journeys.', 1, 'published', now()),
    ('west-africa', 'West Africa', 'West Africa is rich in heritage, coast, music, food, and slower discovery.', 'Choose this region if you are drawn to Atlantic history, contemporary culture, diaspora travel, warm coastal cities, and trips that feel less packaged.', 'West Africa is driven by heritage journeys, winter-sun escapes, coastal cities, and community-grounded experiences. Ghana and Senegal are the most polished starting points, while Benin, Sierra Leone, and Cabo Verde broaden the offer considerably.', 2, 'published', now()),
    ('southern-africa', 'Southern Africa', 'Southern Africa is built for city-and-bush travel, desert roads, waterfalls, and refined wilderness.', 'This region suits travelers who want choice: luxury lodges, self-drive landscapes, wine country, wildlife, coast, design-led cities, and dramatic natural icons.', 'Southern Africa is one of the continent''s most versatile travel regions. South Africa acts as the gateway, Botswana and Namibia deliver high-value wilderness and desert landscapes, and Zimbabwe and Zambia deepen the safari-and-Zambezi story.', 3, 'published', now()),
    ('northern-africa', 'Northern Africa', 'Northern Africa is made for medinas, antiquities, desert routes, coast, and food-led travel.', 'Come here for history, architecture, markets, museums, Mediterranean light, Sahara edges, and shorter itineraries with strong aviation access.', 'Northern Africa is Africa''s volume engine for tourism, driven by Morocco, Egypt, Tunisia, and a growing wave of renewed interest in Algeria. Travelers come for cities, heritage, desert camps, Mediterranean coastlines, and food-led travel.', 4, 'published', now())
on conflict (slug) do update set
    name = excluded.name, hero_title = excluded.hero_title, hero_text = excluded.hero_text,
    overview = excluded.overview, sort_order = excluded.sort_order, status = excluded.status,
    published_at = excluded.published_at, updated_at = now();

with catalogue as (
    select * from jsonb_to_recordset($countries$
        [{"region_slug":"east-africa","slug":"uganda"},{"region_slug":"east-africa","slug":"kenya"},{"region_slug":"east-africa","slug":"tanzania"},{"region_slug":"east-africa","slug":"rwanda"},{"region_slug":"east-africa","slug":"ethiopia"},{"region_slug":"west-africa","slug":"ghana"},{"region_slug":"west-africa","slug":"senegal"},{"region_slug":"west-africa","slug":"benin"},{"region_slug":"west-africa","slug":"sierra-leone"},{"region_slug":"west-africa","slug":"cabo-verde"},{"region_slug":"southern-africa","slug":"south-africa"},{"region_slug":"southern-africa","slug":"botswana"},{"region_slug":"southern-africa","slug":"namibia"},{"region_slug":"southern-africa","slug":"zimbabwe"},{"region_slug":"southern-africa","slug":"zambia"},{"region_slug":"northern-africa","slug":"morocco"},{"region_slug":"northern-africa","slug":"egypt"},{"region_slug":"northern-africa","slug":"tunisia"},{"region_slug":"northern-africa","slug":"algeria"}]
    $countries$::jsonb) as row(region_slug text, slug text)
),
country_content as (
    select * from jsonb_to_recordset($country_content$
        [{"slug":"uganda","hero_title":"Uganda is known as the Pearl of Africa","hero_text":"Uganda is one of Africa's best-value wildlife countries, blending gorilla trekking, chimpanzee tracking, Nile landscapes, and savannah safari parks into one route.","overview":"Its standout combination is unusually concentrated: mountain gorillas and Albertine Rift endemics in the southwest, chimpanzee forests, Nile-based wildlife at Murchison, and savannah circuits linked by road or domestic flight."},
        {"slug":"kenya","hero_title":"Kenya remains the clearest first-time safari gateway","hero_text":"Kenya remains the clearest first-time safari gateway thanks to strong guide networks, the Maasai Mara, private conservancies, and smooth access from Nairobi.","overview":"Beyond the Maasai Mara, Kenya's planning advantages include conservancies, varied public and private safari models, Amboseli's wetland-elephant ecosystem, Laikipia, Rift Valley lakes, and direct Indian Ocean extensions."},
        {"slug":"tanzania","hero_title":"Tanzania delivers cinematic safari landscapes","hero_text":"Tanzania delivers some of Africa's most cinematic safari landscapes, from Serengeti migration scenes to the Ngorongoro Crater and Zanzibar's coast.","overview":"The northern circuit links Tarangire, Ngorongoro, and distinct Serengeti zones, while the south offers lower-density parks and Zanzibar adds a living Swahili heritage landscape rather than beach time alone."},
        {"slug":"rwanda","hero_title":"Rwanda offers premium, compact primate travel","hero_text":"Rwanda offers a premium, compact travel experience with gorilla trekking, polished logistics, and Kigali as one of Africa's easiest arrival cities.","overview":"Volcanoes, Akagera, Nyungwe, and Kigali combine with relatively short road transfers, but premium permit pricing and limited high-demand lodge inventory make advance sequencing essential."},
        {"slug":"ethiopia","hero_title":"Ethiopia appeals to heritage-seeking travelers","hero_text":"Ethiopia appeals to travelers seeking history, ancient religious sites, mountain scenery, and a very different East African experience from safari-led routes.","overview":"Ethiopia's rock-hewn churches, highland landscapes, Islamic and Christian heritage, and regional cultures are exceptional, but flight reliability, regional access, and current official travel advice must be checked close to departure."},
        {"slug":"ghana","hero_title":"Ghana is an accessible West Africa gateway","hero_text":"Ghana is one of West Africa's easiest entry points, combining strong hospitality, heritage travel, Atlantic coast sites, and a vibrant contemporary cultural scene.","overview":"Cape Coast and Elmina demand sensitive heritage interpretation, while Kakum, Accra's arts and food, Kumasi's Asante heritage, and northern landscapes reward a route longer than a simple castle day trip."},
        {"slug":"senegal","hero_title":"Senegal balances urban energy and coastal heritage","hero_text":"Senegal offers one of the region's most polished cultural travel experiences, balancing Dakar's urban energy with coastal heritage and softer delta landscapes.","overview":"Dakar, Gorée, Saint-Louis, the Petite Côte, and the Saloum Delta offer distinct urban, heritage, music, and wetland experiences connected by road and, in the delta, pirogue."},
        {"slug":"benin","hero_title":"Benin rewards cultural curiosity","hero_text":"Benin is small but rich in heritage, especially for travelers interested in Ouidah, Ganvié, royal history, and the living traditions of Vodun culture.","overview":"Ouidah, Abomey, Ganvié, Cotonou, and contemporary Vodun practice should be understood as living cultural landscapes; qualified local guides and respectful photography are central to a responsible visit."},
        {"slug":"sierra-leone","hero_title":"Sierra Leone offers uncrowded Atlantic escapes","hero_text":"Sierra Leone is an emerging leisure destination known for uncrowded beaches, warm hospitality, and a still-lightly-developed coastline.","overview":"The Freetown Peninsula's beaches, Tacugama, Bunce Island, and capital history offer a meaningful route, but road, ferry, weather, and service timing require flexible planning."},
        {"slug":"cabo-verde","hero_title":"Cabo Verde combines island leisure and winter sun","hero_text":"Cabo Verde combines island leisure, winter sun, water sports, and relatively easy resort logistics for travelers who want a lighter Atlantic break.","overview":"The islands differ sharply: Sal and Boa Vista favor resort beaches and wind sports, Santiago carries deeper history, São Vicente centers music and Mindelo, and Santo Antão offers dramatic hiking."},
        {"slug":"south-africa","hero_title":"South Africa is the versatile region","hero_text":"South Africa is the region's most varied travel gateway, offering city design, wine, beaches, and major safari access within one country.","overview":"Its strength is contrast: Cape Town and the Winelands, self-drive national parks, private reserves, the Garden Route, KwaZulu-Natal, and Johannesburg history can be combined without treating the country as one uniform product."},
        {"slug":"botswana","hero_title":"Botswana is high-value conservation travel","hero_text":"Botswana is a high-value safari market built around the Okavango Delta, Chobe, and low-impact conservation-led travel.","overview":"Okavango flood levels, Chobe river ecology, Makgadikgadi seasons, concession rules, and light-aircraft logistics determine the experience more than a generic wet-versus-dry calendar."},
        {"slug":"namibia","hero_title":"Namibia is a road-trip landscape","hero_text":"Namibia is one of Africa's strongest road-trip countries, defined by desert scale, low-density landscapes, and exceptional scenery.","overview":"Sossusvlei, Swakopmund, Damaraland, Etosha, and the far south are separated by long gravel-road distances; fewer bases and longer stays produce a safer, more rewarding itinerary."},
        {"slug":"zimbabwe","hero_title":"Zimbabwe delivers falls and strong guiding","hero_text":"Zimbabwe delivers Victoria Falls, Hwange, and some of Africa's strongest guiding traditions in a more lightly crowded setting.","overview":"Victoria Falls works as both a stand-alone short break and a transition point into Hwange, Chobe, or Zambia. Most travelers arrive through Victoria Falls Airport and transfer into the town hotel zone."},
        {"slug":"zambia","hero_title":"Zambia is revered for walking safaris","hero_text":"Zambia is revered for walking safaris, strong wildlife density, and a rugged sense of authenticity on the Zambezi and Luangwa systems.","overview":"South Luangwa walking safaris, Lower Zambezi river activities, Kafue's scale, and the Zambian side of Victoria Falls are highly seasonal and best matched to camp-opening dates and transport links."},
        {"slug":"morocco","hero_title":"Morocco blends medina culture and desert","hero_text":"Morocco remains one of Africa's easiest culture-forward destinations, blending medinas, design hotels, mountain routes, Atlantic surf, and desert camps.","overview":"Marrakech, Casablanca, and Tangier are the main gateways, with onward movement by rail, private transfer, or domestic flight. Spring and autumn are the most balanced seasons for city touring and desert-edge travel."},
        {"slug":"egypt","hero_title":"Egypt delivers iconic heritage and monuments","hero_text":"Egypt delivers some of the world's most iconic heritage travel, from Cairo and Giza to Nile cities and Red Sea resorts.","overview":"The Giza Plateau and Grand Egyptian Museum now form a powerful paired visit, while Luxor, Aswan, the Nile, Islamic Cairo, Coptic Cairo, and Red Sea routes need structured transport and heat-aware scheduling."},
        {"slug":"tunisia","hero_title":"Tunisia combines medina and Roman ruins","hero_text":"Tunisia combines Mediterranean resort ease with Roman ruins, medinas, and Sahara-edge routes at a relatively accessible price point.","overview":"Tunis, Djerba, and the east-coast resort airports shape most visitor access patterns. Tunis medina, Carthage, Sidi Bou Said, Roman sites such as Dougga and El Jem, Djerba, and Sahara-edge oases create a compact but historically dense route."},
        {"slug":"algeria","hero_title":"Algeria offers Saharan and archaeological rewards","hero_text":"Algeria remains under-visited compared with its neighbors, but it offers major Saharan and archaeological rewards for travelers seeking a less conventional North Africa route.","overview":"Roman cities, the Kasbah of Algiers, M'Zab, and the Tassili plateau offer exceptional heritage with low visitor density, but visa, guide, permit, flight, and security requirements demand specialist planning."}
        ]
    $country_content$::jsonb) as row(slug text, hero_title text, hero_text text, overview text)
)
insert into public.countries (region_id, slug, name, hero_title, hero_text, overview, sort_order, status, published_at)
select region.id, content.slug, initcap(replace(content.slug, '-', ' ')), content.hero_title, content.hero_text, content.overview, row_number() over (order by content.slug), 'published', now()
from content join catalogue on catalogue.slug = content.slug join public.regions as region on region.slug = catalogue.region_slug
on conflict (slug) do update set region_id = excluded.region_id, name = excluded.name, hero_title = excluded.hero_title, hero_text = excluded.hero_text, overview = excluded.overview, sort_order = excluded.sort_order, status = excluded.status, published_at = excluded.published_at, updated_at = now();

insert into public.districts (country_id, slug, name, overview, sort_order)
select country.id, 'primary-district', country.name || ' primary district', 'Local catalogue district for route planning.', 1
from public.countries as country
where not exists (select 1 from public.districts as district where district.country_id = country.id and district.slug = 'primary-district');

with catalogue(slug, country_slug) as (values
    ('bwindi-impenetrable-national-park','uganda'),('murchison-falls-national-park','uganda'),('maasai-mara','kenya'),('amboseli-national-park','kenya'),('serengeti-national-park','tanzania'),('zanzibar','tanzania'),('volcanoes-national-park','rwanda'),('lalibela','ethiopia'),('cape-coast-kakum','ghana'),('sine-saloum-delta','senegal'),('ouidah-and-ganvie','benin'),('tokeh-and-river-no2','sierra-leone'),('sal-island','cabo-verde'),('cape-town','south-africa'),('kruger-national-park','south-africa'),('okavango-delta','botswana'),('namib-desert','namibia'),('victoria-falls','zimbabwe'),('south-luangwa','zambia'),('marrakech-and-atlas','morocco'),('sahara-dunes','morocco'),('cairo-and-giza','egypt'),('tunis-and-sidi-bou-said','tunisia'),('djanet-and-tassili','algeria')
),
attraction_content as (
    select * from jsonb_to_recordset($attraction_content$
        [{"slug":"bwindi-impenetrable-national-park","listing_summary":"Mountain gorilla trekking in one of Africa's most powerful forest landscapes.","detail_intro":"Bwindi Impenetrable National Park shelters fewer than 1,000 mountain gorillas in an ancient Albertine Rift rainforest and UNESCO World Heritage landscape.","full_description":"Bwindi is an ancient, steep-sided Albertine Rift rainforest and a UNESCO World Heritage landscape. Its signature experience is tracking a habituated mountain-gorilla family from one of four UWA entry sectors: Buhoma, Ruhija, Rushaga, or Nkuringo. The forest also rewards birders with Albertine Rift endemics, waterfalls, primates, and community-led cultural walks."},
        {"slug":"murchison-falls-national-park","listing_summary":"Uganda's flagship Nile-and-savannah park with boat safaris, game drives, and the dramatic falls.","detail_intro":"Murchison Falls National Park straddles the Victoria Nile where it is forced through a narrow gorge.","full_description":"Murchison is Uganda's largest national park, where the Victoria Nile is forced through a narrow rock gorge before dropping into the Rift Valley. The classic visit combines northern-bank game drives with a boat journey to the base of the falls, where hippos, crocodiles, elephants, buffalo, and waterbirds gather."},
        {"slug":"maasai-mara","listing_summary":"Kenya's classic safari icon for migration drama, predators, and broad savannah horizons.","detail_intro":"The Maasai Mara is the Kenyan section of the Serengeti-Mara ecosystem, known for open grasslands and exceptional predator density.","full_description":"The Maasai Mara is known for open grasslands, exceptional predator density, and seasonal wildebeest movement across the Mara and Talek rivers. Resident wildlife makes it rewarding beyond migration months, while neighboring conservancies add lower vehicle density, night drives, walking, and closer links with Maasai landowners."},
        {"slug":"amboseli-national-park","listing_summary":"Big-elephant country with unforgettable Kilimanjaro backdrops.","detail_intro":"Amboseli is a compact ecosystem of open plains, acacia woodland, seasonal lakebed, and permanent swamps fed by underground water from Kilimanjaro.","full_description":"Amboseli is a compact ecosystem of open plains, acacia woodland, seasonal lakebed, and permanent swamps fed by underground water from Kilimanjaro. Large, well-studied elephant families are the signature sight."},
        {"slug":"serengeti-national-park","listing_summary":"Vast migration landscapes, apex predators, and one of Africa's strongest safari names.","detail_intro":"Serengeti National Park covers 14,763 square kilometres at the heart of the wider Serengeti-Mara ecosystem.","full_description":"Serengeti National Park covers 14,763 square kilometres at the heart of the wider Serengeti-Mara ecosystem. TANAPA highlights the movement of more than 1.5 million wildebeest with zebra and gazelles, alongside an exceptional concentration of lions, leopards, cheetahs, and hyenas."},
        {"slug":"zanzibar","listing_summary":"A safari-and-coast favorite built around Stone Town, beaches, and slower Indian Ocean pacing.","detail_intro":"Zanzibar combines a living Swahili trading culture with Indian Ocean beaches.","full_description":"Zanzibar combines a living Swahili trading culture with Indian Ocean beaches. Stone Town's coral-stone lanes, carved doors, markets, mosques, and waterfront reveal centuries of African, Arab, Indian, and European exchange. Beyond town, spice farms, Jozani forest, dhow trips, reef excursions, and distinct beach coasts make the island far more varied than a resort extension."},
        {"slug":"volcanoes-national-park","listing_summary":"Premium gorilla trekking with short transfer times from Kigali.","detail_intro":"Volcanoes National Park protects Rwanda's section of the Virunga volcanic range.","full_description":"Volcanoes National Park protects Rwanda's section of the Virunga volcanic range, with bamboo and montane forest beneath peaks such as Karisimbi, Bisoke, and Sabyinyo. Gorilla trekking is the main draw, complemented by golden-monkey tracking, volcano hikes, and the conservation history associated with Dian Fossey."},
        {"slug":"lalibela","listing_summary":"Rock-hewn churches and one of Africa's most compelling heritage landscapes.","detail_intro":"Lalibela is a living Ethiopian Orthodox pilgrimage centre built around eleven medieval churches carved from volcanic rock.","full_description":"Lalibela is a living Ethiopian Orthodox pilgrimage centre built around eleven medieval churches carved from volcanic rock. The churches form northern and southern groups linked by trenches, passages, courtyards, and symbolic references to Jerusalem."},
        {"slug":"cape-coast-kakum","listing_summary":"Atlantic heritage castles paired with Kakum's tropical forest canopy.","detail_intro":"Cape Coast pairs Atlantic forts that document the transatlantic slave trade with Kakum's tropical forest canopy.","full_description":"Cape Coast pairs Atlantic forts that document the transatlantic slave trade with Kakum's tropical forest canopy. Cape Coast Castle's guided route through dungeons, courtyards, museum displays, and the Door of No Return requires time and emotional space."},
        {"slug":"sine-saloum-delta","listing_summary":"A softer Senegal route of waterways, birdlife, and lodge-based slow travel.","detail_intro":"The Saloum Delta is a cultural and ecological landscape of tidal channels, mangroves, islands, shell mounds, fishing villages, and bird colonies.","full_description":"The Saloum Delta is a cultural and ecological landscape of tidal channels, mangroves, islands, shell mounds, fishing villages, and bird colonies. UNESCO recognizes the long relationship between communities and the estuarine environment, including shell accumulations and burial mounds recording centuries of occupation."},
        {"slug":"ouidah-and-ganvie","listing_summary":"A compact heritage route linking Atlantic history with the famous stilt village.","detail_intro":"Ouidah and Ganvié reveal distinct parts of southern Benin.","full_description":"Ouidah and Ganvié reveal distinct parts of southern Benin. Ouidah's museums, sacred sites, and memorial route interpret Vodun traditions and the violence of the transatlantic slave trade. Ganvié, reached by boat across Lake Nokoué, is a living waterside community with homes, schools, worship spaces, transport, and commerce organized around the lake."},
        {"slug":"tokeh-and-river-no2","listing_summary":"An easy Sierra Leone coast escape with striking beaches and a laid-back mood.","detail_intro":"The Freetown Peninsula combines forested hills with broad Atlantic beaches.","full_description":"The Freetown Peninsula combines forested hills with broad Atlantic beaches. Tokeh is known for a long pale-sand bay and resort stays, while River No. 2 is distinguished by its river mouth, community tourism model, seafood lunches, and a dramatic sweep of beach backed by green slopes."},
        {"slug":"sal-island","listing_summary":"Reliable winter sun, beaches, and water sports.","detail_intro":"Sal is Cabo Verde's easiest resort island, but its landscape extends beyond Santa Maria.","full_description":"Sal is Cabo Verde's easiest resort island, but its landscape extends beyond Santa Maria. Pedra de Lume occupies an extinct volcanic crater with historic salt pans, Buracona is known for lava pools and a seasonal Blue Eye light effect, and the trade winds support kitesurfing, windsurfing, and other water sports."},
        {"slug":"cape-town","listing_summary":"A design-led city with ocean views, wine access, and easy day trips.","detail_intro":"Cape Town is a nature-wrapped city centered on Table Mountain and the Cape Peninsula.","full_description":"Cape Town is a nature-wrapped city centered on Table Mountain and the Cape Peninsula. A strong visit balances mountain and coast with layered history: Table Mountain or Lion's Head, Kirstenbosch, Cape Point, penguins at Boulders, Robben Island, District Six, the Bo-Kaap, and food or wine experiences."},
        {"slug":"kruger-national-park","listing_summary":"A major Big Five safari zone with wide lodge choice and strong self-drive options.","detail_intro":"Kruger is a vast public national park with an extensive road network, rest camps, hides, picnic sites, and ecosystems ranging from southern woodland to the drier north.","full_description":"Kruger is a vast public national park with an extensive road network, rest camps, hides, picnic sites, and ecosystems ranging from southern woodland to the drier north. It supports the Big Five, wild dog, cheetah, abundant antelope, and exceptional birdlife, offering both independent self-drive and guided safari options at scale."},
        {"slug":"okavango-delta","listing_summary":"One of Africa's most exclusive safari ecosystems with mokoro channels and floodplain camps.","detail_intro":"The Okavango is a rare inland delta where water from the Angolan highlands spreads into Kalahari sands instead of reaching the sea.","full_description":"The Okavango is a rare inland delta where water from the Angolan highlands spreads into Kalahari sands instead of reaching the sea. Its dry-season flood pulse transforms channels, lagoons, islands, and grasslands, concentrating elephant, buffalo, red lechwe, predators, and prolific birdlife."},
        {"slug":"namib-desert","listing_summary":"Towering dunes, cinematic desert light, and an unmatched sense of open space.","detail_intro":"The Sossusvlei section of the Namib is a landscape of towering red dunes, pale clay pans, dark camel-thorn skeletons, and shifting light.","full_description":"The Sossusvlei section of the Namib is a landscape of towering red dunes, pale clay pans, dark camel-thorn skeletons, and shifting light. Deadvlei's tree silhouettes, climbable dunes, Sesriem Canyon, and vast gravel plains create one of Africa's most recognizable photographic environments."},
        {"slug":"victoria-falls","listing_summary":"The classic waterfall gateway for rainforest walks, river activities, and onward safari routing.","detail_intro":"Mosi-oa-Tunya/Victoria Falls forms the world's largest curtain of falling water, spanning about 1.7 kilometres across the Zambezi gorge.","full_description":"Mosi-oa-Tunya/Victoria Falls forms the world's largest curtain of falling water, spanning about 1.7 kilometres across the Zambezi gorge. Spray, rainbows, basalt gorges, rainforest vegetation, and viewpoints on both Zimbabwean and Zambian sides change dramatically with river level."},
        {"slug":"south-luangwa","listing_summary":"One of Africa's strongest walking safari landscapes.","detail_intro":"South Luangwa is a wildlife-rich valley shaped by the Luangwa River, oxbow lagoons, ebony groves, and seasonal floodplains.","full_description":"South Luangwa is a wildlife-rich valley shaped by the Luangwa River, oxbow lagoons, ebony groves, and seasonal floodplains. It is closely associated with guided walking safaris and is noted for leopard, lion, elephant, hippo, crocodile, and dense game around shrinking dry-season water."},
        {"slug":"marrakech-and-atlas","listing_summary":"A flexible route of medina culture, gardens, riads, and day trips into the Atlas foothills.","detail_intro":"Marrakech combines a nearly thousand-year-old medina with Jemaa el-Fnaa, dense souks, riad courtyards, Islamic architecture, gardens, and contemporary design.","full_description":"Marrakech combines a nearly thousand-year-old medina with Jemaa el-Fnaa, dense souks, riad courtyards, Islamic architecture, gardens, and contemporary design. The nearby High Atlas adds villages, valleys, waterfalls, and trailheads, but mountain trips should be chosen for depth rather than treated as quick photo stops."},
        {"slug":"sahara-dunes","listing_summary":"Desert camps, camel routes, and one of Morocco's most iconic landscape experiences.","detail_intro":"Erg Chebbi is a compact but dramatic field of wind-shaped dunes beside Merzouga.","full_description":"Erg Chebbi is a compact but dramatic field of wind-shaped dunes beside Merzouga. The experience is defined by changing light, ridge walks, camel or four-wheel-drive approaches, desert camps, and clear night skies. Nearby oases, fossil landscapes, and Gnawa music in Khamlia add context."},
        {"slug":"cairo-and-giza","listing_summary":"Pyramids, museums, and Egypt's most powerful urban heritage gateway.","detail_intro":"Cairo and Giza place more than 4,500 years of monumental history beside one of Africa's largest modern cities.","full_description":"Cairo and Giza place more than 4,500 years of monumental history beside one of Africa's largest modern cities. The Giza Plateau contains the pyramids of Khufu, Khafre, and Menkaure, associated temples, smaller pyramids, and the Great Sphinx. The nearby Grand Egyptian Museum brings major collections, including Tutankhamun, into direct conversation with the plateau."},
        {"slug":"tunis-and-sidi-bou-said","listing_summary":"A manageable blend of medina heritage, sea views, and easy cultural touring.","detail_intro":"Greater Tunis layers three experiences: the UNESCO-listed medina, the archaeological landscape of Punic and Roman Carthage, and the blue-and-white hill village of Sidi Bou Said.","full_description":"Greater Tunis layers three experiences: the UNESCO-listed medina, the archaeological landscape of Punic and Roman Carthage, and the blue-and-white hill village of Sidi Bou Said. The medina contains souqs, mosques, madrasas, palaces, and gates; Carthage spreads across multiple sites."},
        {"slug":"djanet-and-tassili","listing_summary":"A saharan expedition route of rock art, desert geology, and extreme remoteness.","detail_intro":"Tassili n'Ajjer is a vast Saharan plateau of eroded sandstone rock forests, arches, canyons, and more than 15,000 recorded paintings and engravings.","full_description":"Tassili n'Ajjer is a vast Saharan plateau of eroded sandstone rock forests, arches, canyons, and more than 15,000 recorded paintings and engravings. The art documents changing climates, wildlife, pastoral life, horses, and camels across millennia, while the geology preserves a lunar landscape carved by water and wind."}
        ]
    $attraction_content$::jsonb) as row(slug text, listing_summary text, detail_intro text, full_description text)
)
insert into public.attractions (region_id, country_id, slug, name, location_name, hero_image_url, hero_image_alt, listing_summary, detail_intro, full_description, sort_order, status, published_at)
select region.id, country.id, catalogue.slug, initcap(replace(catalogue.slug, '-', ' ')), country.name, '/images/stock/destinations/' || catalogue.slug || '.jpg', initcap(replace(catalogue.slug, '-', ' ')), content.listing_summary, content.detail_intro, content.full_description, row_number() over (order by catalogue.slug), 'published', now()
from catalogue join public.countries as country on country.slug = catalogue.country_slug join public.regions as region on region.id = country.region_id join attraction_content as content on content.slug = catalogue.slug
on conflict (slug) do update set region_id = excluded.region_id, country_id = excluded.country_id, name = excluded.name, location_name = excluded.location_name, hero_image_url = excluded.hero_image_url, hero_image_alt = excluded.hero_image_alt, listing_summary = excluded.listing_summary, detail_intro = excluded.detail_intro, full_description = excluded.full_description, sort_order = excluded.sort_order, status = excluded.status, published_at = excluded.published_at, updated_at = now();

with catalogue(slug, country_slug, attraction_slug) as (values
