$media_assignments$::jsonb) as assignment(
        entity_type text,
        entity_slug text,
        role text,
        local_path text,
        alt_text text,
        source_page text,
        creator text,
        license text,
        license_url text,
        exact_subject_match boolean,
        attribution_text text
    )
), owners as (
    select 'attraction'::text as entity_type, id as mediable_id, slug as entity_slug from public.attractions
    union all
    select 'accommodation'::text as entity_type, id as mediable_id, slug as entity_slug from public.accommodations
    union all
    select 'restaurant'::text as entity_type, id as mediable_id, slug as entity_slug from public.restaurants
)
insert into public.media_assets (
    mediable_type, mediable_id, role, local_path, url, alt_text, source_page, creator,
    license, license_url, exact_subject_match, attribution_text, status, published_at, sort_order
)
select assignment.entity_type, owners.mediable_id, assignment.role, assignment.local_path,
    assignment.local_path, assignment.alt_text, assignment.source_page, assignment.creator,
    assignment.license, assignment.license_url, assignment.exact_subject_match,
    assignment.attribution_text, 'published', now(),
    row_number() over (partition by assignment.entity_type order by assignment.entity_slug)
from assignments
join owners using (entity_type, entity_slug)
on conflict (mediable_type, mediable_id, role, source_page) do update set
    local_path = excluded.local_path,
    url = excluded.url,
    alt_text = excluded.alt_text,
    creator = excluded.creator,
    license = excluded.license,
    license_url = excluded.license_url,
    exact_subject_match = excluded.exact_subject_match,
    attribution_text = excluded.attribution_text,
    status = excluded.status,
    published_at = excluded.published_at,
    sort_order = excluded.sort_order,
    updated_at = now();
do $$
begin
    if (select count(*) from public.attractions) < 24 then raise exception 'catalogue incomplete: attractions'; end if;
    if (select count(*) from public.accommodations) < 24 then raise exception 'catalogue incomplete: accommodations'; end if;
    if (select count(*) from public.restaurants) < 24 then raise exception 'catalogue incomplete: restaurants'; end if;
    if (select count(*) from public.media_assets) < 72 then raise exception 'catalogue incomplete: media_assets'; end if;
end;
$$;
